def backfill_products(apps, schema_editor):
    Product = apps.get_model("catalogue", "Product")
    Product.objects.filter(status="approved").update(approved_version=1)
    for product in Product.objects.exclude(size="").iterator():
        match = _SIZE_RE.match(product.size)
        if not match:
            continue  # leave free-text sizes in place; staff can re-enter them structured
        product.size_value = Decimal(match.group(1))
        product.size_unit = _UNIT_CANON[match.group(2).lower()]
        product.save(update_fields=["size_value", "size_unit"])


def seed_taxonomy(apps, schema_editor):
    Industry = apps.get_model("catalogue", "Industry")
    Category = apps.get_model("catalogue", "Category")
    cosmetics, _ = Industry.objects.get_or_create(
        key="cosmetics",
        defaults={
            "label": "Cosmetics & personal care",
            "description": "Skincare, soaps, haircare, perfume, body care",
            "available": True,
            "required_fields": _COSMETIC_REQUIRED,
            "sort_order": 1,
        },
    )
    Industry.objects.get_or_create(
        key="pharmaceuticals",
        defaults={
            "label": "Pharmaceuticals",
            "description": "Locked until the pharmaceutical release gate is complete",
            "available": False,
            "required_fields": _PHARMA_REQUIRED,
            "sort_order": 2,
        },
    )
    for key, label, units in _COSMETIC_CATEGORIES:
        Category.objects.get_or_create(
            industry=cosmetics, key=key, defaults={"label": label, "allowed_units": units}
        )
    # Keep categories already used by existing products resolvable.
    Product = apps.get_model("catalogue", "Product")
    used = set(Product.objects.exclude(category="").values_list("category", flat=True))
    for key in used - set(Category.objects.filter(industry=cosmetics).values_list("key", flat=True)):
        Category.objects.create(industry=cosmetics, key=key, label=key.replace("-", " ").title())


